import sqlite3, json, re
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
# all PK-ish id sets: collect every value of columns named ref_id / *_id that are PKs
pks = {}
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%'")]
for t in tables:
    cols = con.execute(f'PRAGMA table_info("{t}")').fetchall()
    pkcols = [c[1] for c in cols if c[5]]
    if len(pkcols)==1:
        vals = {r[0] for r in con.execute(f'select "{pkcols[0]}" from "{t}"') if r[0] is not None}
        pks[(t,pkcols[0])] = vals
allpk = {}
for k,v in pks.items():
    for x in v:
        allpk.setdefault(str(x), set()).add(k)
# scan TEXT columns for JSON arrays
found = []
total_ptrs = 0
for t in tables:
    cols = con.execute(f'PRAGMA table_info("{t}")').fetchall()
    for c in cols:
        if c[2].upper() != 'TEXT': continue
        n_arr = 0; n_ptr = 0; n_dead = 0; samples=set()
        for (v,) in con.execute(f'select "{c[1]}" from "{t}" where "{c[1]}" is not null'):
            s = v.strip() if isinstance(v,str) else ''
            if not s.startswith('['): continue
            try: arr = json.loads(s)
            except Exception: continue
            if not isinstance(arr, list): continue
            n_arr += 1
            for e in arr:
                if isinstance(e, str) and e in allpk:
                    n_ptr += 1; samples.add(next(iter(allpk[e])))
                elif isinstance(e, str) and re.match(r'^(REF|GAP|D|SLUG|EXT|SL|CA|BPC)-?\d', e):
                    n_dead += 1
        if n_arr:
            found.append((t, c[1], n_arr, n_ptr, n_dead, sorted(samples)))
            total_ptrs += n_ptr
for f in found: print(f)
print("columns holding JSON arrays:", len(found), " columns with >=1 live-pk pointer:", sum(1 for f in found if f[3]), " total pointers:", total_ptrs)
PY

